// SPDX-License-Identifier: MIT
// Minimal SoC: VexiiRiscv (generated by fpga/scripts/cpu/gen_soc.sh) + AMD DDR4 controller + boot ROM, UART, board regs.
//
// Clocks: the CPU, the AXI memory port and the DDR4 controller user interface all run on ui_clk (tCK/4: 333.33 MHz at
//   tCK 750 ps, DDR4-2667), so the memory path has no clock crossing. per_clk (100 MHz) comes from an MMCM on CLK_50M; the
//   peripheral AXI-Lite port crosses to it with an AMD axi_clock_converter.
// Resets: the CPU is held in reset until DDR4 calibration has completed. KEY_PL0 (active high) resets the DDR4 controller
//   and therefore the whole SoC.
// Address map (see docs/validation/soc-minimal.md): DDR4 0x4000_0000 (1 GiB), boot ROM 0x1000_0000 (16 KiB, mirrored in 64 KiB),
//   UART lite 0xF800_0000, board regs 0xF800_1000, CLINT 0xF001_0000, PLIC 0xF0C0_0000.
// `define WITH_DMA when the SoC netlist was generated with --with-dma (the coherent DMA port is tied off).
module soc_top #(
    parameter integer CPU_KHZ = 333333, // ui_clk in kHz, reported by soc_regs; keep in step with the DDR4 TimePeriod
    parameter ROM_INIT = "boot_rom.hex"
) (
    input  wire        clk50,
    input  wire        c0_sys_clk_p,
    input  wire        c0_sys_clk_n,
    output wire [16:0] c0_ddr4_adr,
    output wire [1:0]  c0_ddr4_ba,
    output wire [0:0]  c0_ddr4_bg,
    output wire [0:0]  c0_ddr4_cke,
    output wire [0:0]  c0_ddr4_odt,
    output wire [0:0]  c0_ddr4_cs_n,
    output wire [0:0]  c0_ddr4_ck_t,
    output wire [0:0]  c0_ddr4_ck_c,
    output wire        c0_ddr4_act_n,
    output wire        c0_ddr4_par,
    output wire        c0_ddr4_reset_n,
    inout  wire [3:0]  c0_ddr4_dm_dbi_n,
    inout  wire [31:0] c0_ddr4_dq,
    inout  wire [3:0]  c0_ddr4_dqs_t,
    inout  wire [3:0]  c0_ddr4_dqs_c,
    input  wire        key_rst,
    output wire [7:0]  led,
    input  wire [3:1]  key_k,  // KEY_PL1-3 (KEY_PL0 is key_rst), bank 65, 1.2 V
    input  wire [3:0]  sw,     // SW1-SW4 DIP switches, bank 65, 1.2 V
    output wire        uart_tx,
    input  wire        uart_rx,
    output wire        sd_clk,
    output wire        sd_cmd,   // SPI MOSI
    input  wire        sd_dat0,  // SPI MISO
    output wire        sd_dat3,  // SPI chip select (active low)
    // Small peripherals: MS5611 barometer on its own SPI port (bank 86, 3.3 V), DS18B20 1-Wire (bank 86), buzzer, 4-wire fan (bank 67, VADJ 1.8 V)
    output wire        ms_sclk,
    output wire        ms_mosi,
    input  wire        ms_miso,
    output wire        ms_cs_n,
    inout  wire        ds18b20_io,
    output wire        beep,
    output wire        fan_pwm,
    input  wire        fan_fb,
    // I2C buses with board pull-ups (bank 84 and bank 86, both 3.3 V): PL_I2C (BL24C02) and the second bus (2 x BL24C256)
    inout  wire        i2c0_scl,
    inout  wire        i2c0_sda,
    inout  wire        i2c1_scl,
    inout  wire        i2c1_sda,
    // RTL8211EG in GMII mode (bank 87, 3.3 V). MDC/MDIO/INT/COL/CRS have no FPGA pin.
    input  wire        eth_rx_clk,
    output wire        eth_gtx_clk,
    output wire        eth_rst_n,
    output wire [7:0]  eth_txd,
    output wire        eth_tx_en,
    output wire        eth_tx_er,
    input  wire [7:0]  eth_rxd,
    input  wire        eth_rx_dv,
    input  wire        eth_rx_er
);
    // ---------------------------------------------------------------- clocks and resets
    wire clk50_ibuf, mmcm_fb, mmcm_locked, per_clk_raw, per_clk, eth_clk125;
    wire ui_clk, ui_rst, calib;
    wire ddr_half;
    wire cpu_clk = ui_clk;

    IBUF u_clk50_ibuf (.I(clk50), .O(clk50_ibuf));
    MMCME4_ADV #(
        .CLKIN1_PERIOD(20.0),
        .DIVCLK_DIVIDE(1),
        .CLKFBOUT_MULT_F(20.0),   // 1000 MHz VCO
        .CLKOUT0_DIVIDE_F(10.0),  // 100 MHz
        .CLKOUT1_DIVIDE(8)        // 125 MHz: GTX_CLK and the Ethernet TX domain (the PHY has no RX clock before link)
    ) u_mmcm (
        .CLKIN1(clk50_ibuf), .CLKIN2(1'b0), .CLKINSEL(1'b1),
        .CLKFBIN(mmcm_fb), .CLKFBOUT(mmcm_fb),
        .CLKOUT0(per_clk_raw), .CLKOUT1(eth_clk125),
        .LOCKED(mmcm_locked), .RST(1'b0), .PWRDWN(1'b0),
        .DADDR(7'd0), .DCLK(1'b0), .DEN(1'b0), .DI(16'd0), .DWE(1'b0),
        .PSCLK(1'b0), .PSEN(1'b0), .PSINCDEC(1'b0));
    BUFG u_bufg_per (.I(per_clk_raw), .O(per_clk));

    reg [2:0] cpu_rst_q = 3'b000;
    reg [2:0] per_rst_q = 3'b000;
    always @(posedge cpu_clk or negedge calib)
        if (!calib) cpu_rst_q <= 3'b000;
        else cpu_rst_q <= {cpu_rst_q[1:0], 1'b1};
    always @(posedge per_clk or negedge mmcm_locked)
        if (!mmcm_locked) per_rst_q <= 3'b000;
        else per_rst_q <= {per_rst_q[1:0], 1'b1};
    wire cpu_rst_n = cpu_rst_q[2];
    wire per_rst_n = per_rst_q[2];
    wire cpu_reset = ~cpu_rst_n;
    wire ui_rst_n = ~ui_rst;

    // ---------------------------------------------------------------- CPU SoC
    wire        m_awvalid, m_awready, m_wvalid, m_wready, m_wlast, m_bvalid, m_bready;
    wire        m_arvalid, m_arready, m_rvalid, m_rready, m_rlast;
    wire [31:0] m_awaddr, m_araddr;
    wire [7:0]  m_awid, m_arid, m_awlen, m_arlen, m_bid, m_rid;
    wire [2:0]  m_awsize, m_arsize;
    wire [1:0]  m_awburst, m_arburst, m_bresp, m_rresp;
    wire [255:0] m_wdata, m_rdata;
    wire [31:0] m_wstrb;

    wire        p_awvalid, p_awready, p_wvalid, p_wready, p_bvalid, p_bready;
    wire        p_arvalid, p_arready, p_rvalid, p_rready;
    wire [31:0] p_awaddr, p_araddr, p_wdata, p_rdata;
    wire [2:0]  p_awprot, p_arprot;
    wire [3:0]  p_wstrb;
    wire [1:0]  p_bresp, p_rresp;

    wire        uart_irq_pulse, uart_irq;
    wire        spi_irq_level, spi_irq;
    wire        eth_irq;
    // The peripheral interrupts come from per_clk; synchronize them into the CPU clock before they reach the PLIC gateways.
    // PLIC sources: 1 UART lite, 2 SPI (SD), 3 LiteEth, 4 SPI (MS5611), 5 GPIO.
    wire        spi1_irq_level, spi1_irq, gpio_irq;
    wire [6:0]  irq_sync_q;
    wire        i2c0_irq, i2c1_irq, dma_irq;
    irq_sync #(.W(8)) u_irq_sync (.clk(cpu_clk), .d({dma_irq, i2c1_irq, i2c0_irq, gpio_irq, spi1_irq, eth_irq, spi_irq, uart_irq}), .q(irq_sync_q));
    wire [31:0] irq = {24'd0, irq_sync_q, 1'b0};

`ifdef WITH_DMA
    // Hub DMA port, driven by the eth_dma engine through cc_dma (write only; the read channels are tied off).
    wire        dma_awvalid, dma_awready, dma_wvalid, dma_wready, dma_wlast, dma_bvalid, dma_bready, dma_arready, dma_rvalid, dma_rlast;
    wire [31:0] dma_awaddr;
    wire [7:0]  dma_awlen, dma_wstrb;
    wire [2:0]  dma_awsize;
    wire [1:0]  dma_awburst;
    wire [63:0] dma_wdata, dma_rdata;
    wire [3:0]  dma_bid, dma_rid;
    wire [1:0]  dma_bresp, dma_rresp;
`endif

    `SOC_MODULE u_soc (
        .litex_clk(cpu_clk),
        .litex_reset(cpu_reset),
        .peripheral_externalInterrupts_port(irq),
        .mBus_awvalid(m_awvalid), .mBus_awready(m_awready), .mBus_awaddr(m_awaddr), .mBus_awid(m_awid),
        .mBus_awlen(m_awlen), .mBus_awsize(m_awsize), .mBus_awburst(m_awburst), .mBus_awallStrb(),
        .mBus_wvalid(m_wvalid), .mBus_wready(m_wready), .mBus_wdata(m_wdata), .mBus_wstrb(m_wstrb), .mBus_wlast(m_wlast),
        .mBus_bvalid(m_bvalid), .mBus_bready(m_bready), .mBus_bid(m_bid), .mBus_bresp(m_bresp),
        .mBus_arvalid(m_arvalid), .mBus_arready(m_arready), .mBus_araddr(m_araddr), .mBus_arid(m_arid),
        .mBus_arlen(m_arlen), .mBus_arsize(m_arsize), .mBus_arburst(m_arburst),
        .mBus_rvalid(m_rvalid), .mBus_rready(m_rready), .mBus_rdata(m_rdata), .mBus_rid(m_rid),
        .mBus_rresp(m_rresp), .mBus_rlast(m_rlast),
        .pBus_awvalid(p_awvalid), .pBus_awready(p_awready), .pBus_awaddr(p_awaddr), .pBus_awprot(p_awprot),
        .pBus_wvalid(p_wvalid), .pBus_wready(p_wready), .pBus_wdata(p_wdata), .pBus_wstrb(p_wstrb),
        .pBus_bvalid(p_bvalid), .pBus_bready(p_bready), .pBus_bresp(p_bresp),
        .pBus_arvalid(p_arvalid), .pBus_arready(p_arready), .pBus_araddr(p_araddr), .pBus_arprot(p_arprot),
        .pBus_rvalid(p_rvalid), .pBus_rready(p_rready), .pBus_rdata(p_rdata), .pBus_rresp(p_rresp),
`ifdef WITH_DMA
        .dma_bus_awvalid(dma_awvalid), .dma_bus_awready(dma_awready), .dma_bus_awaddr(dma_awaddr), .dma_bus_awid(4'd0),
        .dma_bus_awregion(4'd0), .dma_bus_awlock(1'b0), .dma_bus_awcache(4'd0), .dma_bus_awqos(4'd0), .dma_bus_awprot(3'd0),
        .dma_bus_awlen(dma_awlen), .dma_bus_awsize(dma_awsize), .dma_bus_awburst(dma_awburst),
        .dma_bus_wvalid(dma_wvalid), .dma_bus_wready(dma_wready), .dma_bus_wdata(dma_wdata), .dma_bus_wstrb(dma_wstrb), .dma_bus_wlast(dma_wlast),
        .dma_bus_bvalid(dma_bvalid), .dma_bus_bready(dma_bready), .dma_bus_bid(dma_bid), .dma_bus_bresp(dma_bresp),
        .dma_bus_arvalid(1'b0), .dma_bus_arready(dma_arready), .dma_bus_araddr(32'd0), .dma_bus_arid(4'd0),
        .dma_bus_arregion(4'd0), .dma_bus_arlock(1'b0), .dma_bus_arcache(4'd0), .dma_bus_arqos(4'd0), .dma_bus_arprot(3'd0),
        .dma_bus_arlen(8'd0), .dma_bus_arsize(3'd0), .dma_bus_arburst(2'd1),
        .dma_bus_rvalid(dma_rvalid), .dma_bus_rready(1'b1), .dma_bus_rdata(dma_rdata), .dma_bus_rid(dma_rid),
        .dma_bus_rresp(dma_rresp), .dma_bus_rlast(dma_rlast),
`endif
        .debug());

    // ---------------------------------------------------------------- memory path: CPU AXI port -> DDR4 controller
    wire [3:0]  d_awcache = 4'd0, d_arcache = 4'd0, d_awqos = 4'd0, d_arqos = 4'd0;
    wire [2:0]  d_awprot = 3'd0, d_arprot = 3'd0;
    wire        d_awlock = 1'b0, d_arlock = 1'b0;

    // CA parity is disabled in the controller, which then has no PAR port; drive the DRAM PAR input low (DDR4 needs a valid level).
    assign c0_ddr4_par = 1'b0;

    `ifdef DDR_8G
    // Capacity-test build (8 Gb controller): DDRHALF selects the upper 1 GiB half in the top 256 MiB of the window (ddr_halfmap.v).
    // The select is static during a test, so a two-flop synchronizer into ui_clk is enough.
    (* ASYNC_REG = "TRUE" *) reg [1:0] ddr_half_s;
    always @(posedge ui_clk) ddr_half_s <= {ddr_half_s[0], ddr_half};
    wire [30:0] d_awaddr, d_araddr;
    ddr_halfmap u_halfmap_w (.addr(m_awaddr[29:0]), .sel(ddr_half_s[1]), .ddr_addr(d_awaddr));
    ddr_halfmap u_halfmap_r (.addr(m_araddr[29:0]), .sel(ddr_half_s[1]), .ddr_addr(d_araddr));
`else
    wire [29:0] d_awaddr = m_awaddr[29:0];
    wire [29:0] d_araddr = m_araddr[29:0];
`endif
ddr4_0 u_ddr4 (
        .c0_init_calib_complete(calib),
        .dbg_clk(),
        .c0_sys_clk_p(c0_sys_clk_p),
        .c0_sys_clk_n(c0_sys_clk_n),
        .dbg_bus(),
        .c0_ddr4_adr(c0_ddr4_adr),
        .c0_ddr4_ba(c0_ddr4_ba),
        .c0_ddr4_cke(c0_ddr4_cke),
        .c0_ddr4_cs_n(c0_ddr4_cs_n),
        .c0_ddr4_dm_dbi_n(c0_ddr4_dm_dbi_n),
        .c0_ddr4_dq(c0_ddr4_dq),
        .c0_ddr4_dqs_c(c0_ddr4_dqs_c),
        .c0_ddr4_dqs_t(c0_ddr4_dqs_t),
        .c0_ddr4_odt(c0_ddr4_odt),
        .c0_ddr4_bg(c0_ddr4_bg),
        .c0_ddr4_reset_n(c0_ddr4_reset_n),
        .c0_ddr4_act_n(c0_ddr4_act_n),
        .c0_ddr4_ck_c(c0_ddr4_ck_c),
        .c0_ddr4_ck_t(c0_ddr4_ck_t),
        .c0_ddr4_ui_clk(ui_clk),
        .c0_ddr4_ui_clk_sync_rst(ui_rst),
        .c0_ddr4_aresetn(ui_rst_n),
        .c0_ddr4_s_axi_awid(m_awid),
        .c0_ddr4_s_axi_awaddr(d_awaddr),
        .c0_ddr4_s_axi_awlen(m_awlen),
        .c0_ddr4_s_axi_awsize(m_awsize),
        .c0_ddr4_s_axi_awburst(m_awburst),
        .c0_ddr4_s_axi_awlock(d_awlock),
        .c0_ddr4_s_axi_awcache(d_awcache),
        .c0_ddr4_s_axi_awprot(d_awprot),
        .c0_ddr4_s_axi_awqos(d_awqos),
        .c0_ddr4_s_axi_awvalid(m_awvalid),
        .c0_ddr4_s_axi_awready(m_awready),
        .c0_ddr4_s_axi_wdata(m_wdata),
        .c0_ddr4_s_axi_wstrb(m_wstrb),
        .c0_ddr4_s_axi_wlast(m_wlast),
        .c0_ddr4_s_axi_wvalid(m_wvalid),
        .c0_ddr4_s_axi_wready(m_wready),
        .c0_ddr4_s_axi_bready(m_bready),
        .c0_ddr4_s_axi_bid(m_bid),
        .c0_ddr4_s_axi_bresp(m_bresp),
        .c0_ddr4_s_axi_bvalid(m_bvalid),
        .c0_ddr4_s_axi_arid(m_arid),
        .c0_ddr4_s_axi_araddr(d_araddr),
        .c0_ddr4_s_axi_arlen(m_arlen),
        .c0_ddr4_s_axi_arsize(m_arsize),
        .c0_ddr4_s_axi_arburst(m_arburst),
        .c0_ddr4_s_axi_arlock(d_arlock),
        .c0_ddr4_s_axi_arcache(d_arcache),
        .c0_ddr4_s_axi_arprot(d_arprot),
        .c0_ddr4_s_axi_arqos(d_arqos),
        .c0_ddr4_s_axi_arvalid(m_arvalid),
        .c0_ddr4_s_axi_arready(m_arready),
        .c0_ddr4_s_axi_rready(m_rready),
        .c0_ddr4_s_axi_rlast(m_rlast),
        .c0_ddr4_s_axi_rvalid(m_rvalid),
        .c0_ddr4_s_axi_rresp(m_rresp),
        .c0_ddr4_s_axi_rid(m_rid),
        .c0_ddr4_s_axi_rdata(m_rdata),
        .sys_rst(key_rst));

    // ---------------------------------------------------------------- peripheral path: CPU clock -> per_clk
    wire        q_awvalid, q_awready, q_wvalid, q_wready, q_bvalid, q_bready;
    wire        q_arvalid, q_arready, q_rvalid, q_rready;
    wire [31:0] q_awaddr, q_araddr, q_wdata, q_rdata;
    wire [2:0]  q_awprot, q_arprot;
    wire [3:0]  q_wstrb;
    wire [1:0]  q_bresp, q_rresp;

    cc_per u_cc_per (
        .s_axi_aclk(cpu_clk), .s_axi_aresetn(cpu_rst_n),
        .s_axi_awaddr(p_awaddr), .s_axi_awprot(p_awprot), .s_axi_awvalid(p_awvalid), .s_axi_awready(p_awready),
        .s_axi_wdata(p_wdata), .s_axi_wstrb(p_wstrb), .s_axi_wvalid(p_wvalid), .s_axi_wready(p_wready),
        .s_axi_bresp(p_bresp), .s_axi_bvalid(p_bvalid), .s_axi_bready(p_bready),
        .s_axi_araddr(p_araddr), .s_axi_arprot(p_arprot), .s_axi_arvalid(p_arvalid), .s_axi_arready(p_arready),
        .s_axi_rdata(p_rdata), .s_axi_rresp(p_rresp), .s_axi_rvalid(p_rvalid), .s_axi_rready(p_rready),
        .m_axi_aclk(per_clk), .m_axi_aresetn(per_rst_n),
        .m_axi_awaddr(q_awaddr), .m_axi_awprot(q_awprot), .m_axi_awvalid(q_awvalid), .m_axi_awready(q_awready),
        .m_axi_wdata(q_wdata), .m_axi_wstrb(q_wstrb), .m_axi_wvalid(q_wvalid), .m_axi_wready(q_wready),
        .m_axi_bresp(q_bresp), .m_axi_bvalid(q_bvalid), .m_axi_bready(q_bready),
        .m_axi_araddr(q_araddr), .m_axi_arprot(q_arprot), .m_axi_arvalid(q_arvalid), .m_axi_arready(q_arready),
        .m_axi_rdata(q_rdata), .m_axi_rresp(q_rresp), .m_axi_rvalid(q_rvalid), .m_axi_rready(q_rready));

    // crossbar masters: 0 UART lite, 1 board regs, 2 boot ROM, 3 SPI (SD card), 4 LiteEth (CSR/MDIO 0xF8008000 16 KiB and packet buffers 0xF800C000 8 KiB, remapped below),
    // 5 AXI GPIO 0xF8003000, 6 AXI Timer (PWM) 0xF8004000, 7 SPI (MS5611) 0xF8005000,
    // 8 AXI IIC (PL_I2C) 0xF8006000, 9 AXI IIC (second bus) 0xF8007000
    wire [351:0] x_awaddr, x_araddr, x_wdata, x_rdata;
    wire [32:0] x_awprot, x_arprot;
    wire [43:0] x_wstrb;
    wire [21:0] x_bresp, x_rresp;
    wire [10:0] x_awvalid, x_awready, x_wvalid, x_wready, x_bvalid, x_bready;
    wire [10:0] x_arvalid, x_arready, x_rvalid, x_rready;

    // second crossbar master: the DMA engine's source reads (write channels tied off)
    wire [31:0] dm_araddr, dm_rdata;
    wire        dm_arvalid, dm_rready;
    wire [1:0]  dm_rresp;
    wire [1:0]  xs_awready, xs_wready, xs_bvalid, xs_arready, xs_rvalid;
    wire [3:0]  xs_bresp, xs_rresp;
    wire [63:0] xs_rdata;

    xbar_per u_xbar (
        .aclk(per_clk), .aresetn(per_rst_n),
        .s_axi_awaddr({32'd0, q_awaddr}), .s_axi_awprot({3'd0, q_awprot}), .s_axi_awvalid({1'b0, q_awvalid}), .s_axi_awready(xs_awready),
        .s_axi_wdata({32'd0, q_wdata}), .s_axi_wstrb({4'd0, q_wstrb}), .s_axi_wvalid({1'b0, q_wvalid}), .s_axi_wready(xs_wready),
        .s_axi_bresp(xs_bresp), .s_axi_bvalid(xs_bvalid), .s_axi_bready({1'b1, q_bready}),
        .s_axi_araddr({dm_araddr, q_araddr}), .s_axi_arprot({3'd0, q_arprot}), .s_axi_arvalid({dm_arvalid, q_arvalid}), .s_axi_arready(xs_arready),
        .s_axi_rdata(xs_rdata), .s_axi_rresp(xs_rresp), .s_axi_rvalid(xs_rvalid), .s_axi_rready({dm_rready, q_rready}),
        .m_axi_awaddr(x_awaddr), .m_axi_awprot(x_awprot), .m_axi_awvalid(x_awvalid), .m_axi_awready(x_awready),
        .m_axi_wdata(x_wdata), .m_axi_wstrb(x_wstrb), .m_axi_wvalid(x_wvalid), .m_axi_wready(x_wready),
        .m_axi_bresp(x_bresp), .m_axi_bvalid(x_bvalid), .m_axi_bready(x_bready),
        .m_axi_araddr(x_araddr), .m_axi_arprot(x_arprot), .m_axi_arvalid(x_arvalid), .m_axi_arready(x_arready),
        .m_axi_rdata(x_rdata), .m_axi_rresp(x_rresp), .m_axi_rvalid(x_rvalid), .m_axi_rready(x_rready));

    assign q_awready = xs_awready[0];
    assign q_wready = xs_wready[0];
    assign q_bresp = xs_bresp[1:0];
    assign q_bvalid = xs_bvalid[0];
    assign q_arready = xs_arready[0];
    assign q_rdata = xs_rdata[31:0];
    assign q_rresp = xs_rresp[1:0];
    assign q_rvalid = xs_rvalid[0];
    assign dm_rdata = xs_rdata[63:32];
    assign dm_rresp = xs_rresp[3:2];

    uart_0 u_uart (
        .s_axi_aclk(per_clk), .s_axi_aresetn(per_rst_n), .interrupt(uart_irq_pulse),
        .s_axi_awaddr(x_awaddr[3:0]), .s_axi_awvalid(x_awvalid[0]), .s_axi_awready(x_awready[0]),
